/// Commands the runtime adds to the root; generated resources must not take these names.
pub const BUILTINS: [&str; 6] = ["auth", "completion", "man", "schema", "agents", "mcp"];

/// Adds the global options and the built-in commands to the generated root command. Global
/// options are listed in the root's help only: the others point to it. The commands
/// `[context.cli.operations.<tool>]` hides are left out of help, completions and man pages.
pub fn command(app: &App, root: Command) -> Command {
    let schema = Schema::parse(app.schema).ok();
    let prefix = app.env_prefix;
    let tty_format = app.default_format.map_or("table", Format::name);
    let globals = [
        Arg::new(ids::FORMAT)
            .long(ids::FORMAT)
            .value_name("FORMAT")
            .value_parser(Format::NAMES)
            .hide_possible_values(true)
            .help(format!("json, jsonl, yaml or table [env: {prefix}_FORMAT] [default: {tty_format} on a terminal, else json; jsonl for lists and streams]")),
        Arg::new(ids::JQ)
            .long(ids::JQ)
            .value_name("FILTER")
            .help("jq filter (jaq: jq's builtins, @csv, @tsv...), run on each item of a list, on the whole array with --format json; strings print raw"),
        Arg::new(ids::PRETTY)
            .long(ids::PRETTY)
            .action(ArgAction::SetTrue)
            .help("Indent JSON off a terminal too"),
        Arg::new(ids::MAX_ITEMS)
            .long(ids::MAX_ITEMS)
            .value_name("N")
            .value_parser(value_parser!(usize))
            .help("Stop lists after N items, fetching no further page"),
        Arg::new(ids::ALL)
            .long(ids::ALL)
            .action(ArgAction::SetTrue)
            .help("Fetch every page of a list on a terminal too, which shows the first page"),
        Arg::new(ids::DRY_RUN)
            .long(ids::DRY_RUN)
            .action(ArgAction::SetTrue)
            .help("Print the request as JSON instead of sending it: method, url, query, headers, body"),
        Arg::new(ids::ALLOW_UNKNOWN_FIELDS)
            .long(ids::ALLOW_UNKNOWN_FIELDS)
            .action(ArgAction::SetTrue)
            .help("Send body fields and enum values the schema does not know"),
        Arg::new(ids::PROFILE)
            .long(ids::PROFILE)
            .value_name("NAME")
            .help(format!("Profile of the config file to use [env: {prefix}_PROFILE]")),
        Arg::new(ids::API_KEY)
            .long(ids::API_KEY)
            .value_name("KEY")
            .help(format!("API key [env: {prefix}_API_KEY]")),
        Arg::new(ids::BASE_URL)
            .long(ids::BASE_URL)
            .value_name("URL")
            .help(format!("API base URL [env: {prefix}_BASE_URL]")),
        Arg::new(ids::RETRIES)
            .long(ids::RETRIES)
            .value_name("N")
            .value_parser(value_parser!(u32))
            .conflicts_with(ids::NO_RETRY)
            .help(format!("Retry a request up to N times on no response, 408, 429 or 5xx, if idempotent or with an idempotency key [env: {prefix}_RETRIES] [default: 2]")),
        Arg::new(ids::NO_RETRY)
            .long(ids::NO_RETRY)
            .action(ArgAction::SetTrue)
            .help("Never retry, as --retries 0"),
        Arg::new(ids::TIMEOUT)
            .long(ids::TIMEOUT)
            .value_name("SECS")
            .value_parser(retry::seconds)
            .help(format!("Timeout of each attempt in seconds, 0 for none [env: {prefix}_TIMEOUT] [default: the SDK's]")),
        Arg::new(ids::NO_COLOR)
            .long(ids::NO_COLOR)
            .action(ArgAction::SetTrue)
            .help("Disable colors (also when NO_COLOR is set)"),
        Arg::new(ids::DEBUG)
            .long(ids::DEBUG)
            .action(ArgAction::SetTrue)
            .help("Print diagnostics to stderr"),
    ];
    let listed = global_help(&globals);
    let pointer = format!(
        "Global options: {}; see `{} --help`",
        globals
            .iter()
            .filter_map(|arg| arg.get_long())
            .map(|long| format!("--{long}"))
            .collect::<Vec<_>>()
            .join(" "),
        app.name
    );
    let root = root
        .subcommand(
            Command::new("schema")
                .about("Print the JSON Schema of a command's input, or the index of commands")
                .long_about(
                    "Print, as JSON, the index of the commands under the words given (all without \
                     any), or for a command the JSON Schema of its parameters and body, with an \
                     example body; --response gives what it prints.",
                )
                .arg(Arg::new("command").num_args(0..).value_name("COMMAND"))
                .arg(
                    Arg::new("response")
                        .long("response")
                        .action(ArgAction::SetTrue)
                        .help("The schema of what the command prints"),
                ),
        )
        .subcommand(
            Command::new("agents")
                .about("How to use this CLI from scripts and agents: output, errors, discovery"),
        )
        .subcommand(mcp::command(app, schema.as_ref()));
    let root = root
        .subcommand_required(true)
        .arg_required_else_help(true)
        .args(globals.map(|arg| arg.global(true).hide(true)))
        .after_help(listed)
        .subcommand(auth::command(app))
        .subcommand(
            Command::new("completion")
                .about("Print a shell completion script")
                .arg(
                    Arg::new("shell")
                        .required(true)
                        .value_parser(value_parser!(Shell)),
                ),
        )
        .subcommand(
            Command::new("man")
                .hide(true)
                .about("Print the man page, or write every page to a directory")
                .arg(
                    Arg::new("out-dir")
                        .long("out-dir")
                        .value_name("DIR")
                        .value_parser(value_parser!(PathBuf)),
                ),
        );
    let root = point_to_globals(root, &pointer, app.name, &[]);
    match schema.map(|schema| hidden(&schema)) {
        Some(hidden) if !hidden.is_empty() => hide(root, &hidden, &[]),
        _ => root,
    }
}

/// The words of the commands `[context.cli.operations.<tool>] hidden` hides, `<tool>` being the
/// name of their MCP tool before `[context.cli_mcp]` renames it.
fn hidden(schema: &Schema) -> Vec<String> {
    let operations = &schema.cli()["operations"];
    (schema.index(&[]).into_iter())
        .filter_map(|entry| entry["command"].as_str().map(str::to_owned))
        .filter(|words| operations[mcp::tool_name(words)]["hidden"] == true)
        .collect()
}

/// Hides the commands under `cmd` whose words are `hidden`, and those whose every command is.
fn hide(cmd: Command, hidden: &[String], words: &[&str]) -> Command {
    let subcommands: Vec<String> = cmd
        .get_subcommands()
        .map(|sub| sub.get_name().to_owned())
        .collect();
    subcommands.into_iter().fold(cmd, |cmd, name| {
        cmd.mut_subcommand(&name, |sub| {
            let words = [words, &[name.as_str()]].concat();
            if hidden.contains(&words.join(" ")) {
                return sub.hide(true);
            }
            let sub = hide(sub, hidden, &words);
            match sub.has_subcommands() && sub.get_subcommands().all(Command::is_hide_set) {
                true => sub.hide(true),
                false => sub,
            }
        })
    })
}

/// The help of the global options, which are hidden from every command but listed here.
fn global_help(globals: &[Arg]) -> String {
    let lines: Vec<(String, String)> = globals
        .iter()
        .map(|arg| {
            let long = arg.get_long().unwrap_or_default();
            let flag = match arg.get_value_names() {
                Some([value, ..]) if arg.get_num_args().is_none_or(|n| n.max_values() > 0) => {
                    format!("--{long} <{value}>")
                }
                _ => format!("--{long}"),
            };
            (
                flag,
                arg.get_help().map(ToString::to_string).unwrap_or_default(),
            )
        })
        .collect();
    let width = lines.iter().map(|(flag, _)| flag.len()).max().unwrap_or(0);
    let lines: Vec<String> = lines
        .iter()
        .map(|(flag, help)| format!("      {flag:width$}  {help}"))
        .collect();
    format!("Global options:\n{}", lines.join("\n"))
}

/// Adds `pointer` after the help of every command under `cmd`, whose long help may say
/// `{bin}` and `{words}` for the binary's name and the command's words.
fn point_to_globals(cmd: Command, pointer: &str, bin: &str, words: &[&str]) -> Command {
    let subcommands: Vec<String> = cmd
        .get_subcommands()
        .map(|sub| sub.get_name().to_owned())
        .collect();
    subcommands.into_iter().fold(cmd, |cmd, name| {
        cmd.mut_subcommand(&name, |sub| {
            let words = [words, &[name.as_str()]].concat();
            let sub = point_to_globals(sub, pointer, bin, &words);
            let sub = match sub.get_after_long_help().map(ToString::to_string) {
                Some(long) => {
                    let long = long
                        .replace("{bin}", bin)
                        .replace("{words}", &words.join(" "));
                    sub.after_long_help(format!("{long}\n\n{pointer}"))
                }
                None => sub,
            };
            match sub.get_after_help().map(ToString::to_string) {
                Some(after) => sub.after_help(format!("{after}\n\n{pointer}")),
                None => sub.after_help(pointer.to_owned()),
            }
        })
    })
}

/// The global options, as given on the command line.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Globals {
    pub format: Option<Format>,
    pub jq: Option<String>,
    pub pretty: bool,
    pub dry_run: bool,
    pub all: bool,
    pub allow_unknown_fields: bool,
    pub profile: Option<String>,
    pub api_key: Option<String>,
    pub base_url: Option<String>,
    pub max_items: Option<usize>,
    pub no_color: bool,
    pub debug: bool,
    pub retries: Option<u32>,
    pub no_retry: bool,
    /// Zero for no timeout.
    pub timeout: Option<Duration>,
}

/// Reads the global options back from any level of the matches.
pub fn globals(matches: &ArgMatches) -> Globals {
    let string = |id: &str| matches.get_one::<String>(id).cloned();
    Globals {
        format: string(ids::FORMAT).as_deref().and_then(Format::parse),
        jq: string(ids::JQ),
        pretty: matches.get_flag(ids::PRETTY),
        dry_run: matches.get_flag(ids::DRY_RUN),
        all: matches.get_flag(ids::ALL),
        allow_unknown_fields: matches.get_flag(ids::ALLOW_UNKNOWN_FIELDS),
        profile: string(ids::PROFILE),
        api_key: string(ids::API_KEY),
        base_url: string(ids::BASE_URL),
        max_items: matches.get_one::<usize>(ids::MAX_ITEMS).copied(),
        no_color: matches.get_flag(ids::NO_COLOR),
        debug: matches.get_flag(ids::DEBUG),
        retries: matches.get_one::<u32>(ids::RETRIES).copied(),
        no_retry: matches.get_flag(ids::NO_RETRY),
        timeout: matches.get_one::<Duration>(ids::TIMEOUT).copied(),
    }
}

/// The process around the CLI: streams, terminals, environment, config directory.
/// [`Host::system`] in `main`, [`Host::captured`] in tests.
pub struct Host {
    pub stdout: Box<dyn Write>,
    pub stderr: Box<dyn Write>,
    pub stdin: Box<dyn Read + Send>,
    pub stdout_tty: bool,
    pub stderr_tty: bool,
    pub stdin_tty: bool,
    pub env: HashMap<String, String>,
    pub config_dir: Option<PathBuf>,
    /// Table width on a terminal; `None` asks the terminal.
    pub width: Option<u16>,
}

impl Host {
    pub fn system() -> Self {
        let env: HashMap<String, String> = std::env::vars_os()
            .filter_map(|(key, value)| Some((key.into_string().ok()?, value.into_string().ok()?)))
            .collect();
        Self {
            stdout: Box::new(io::stdout()),
            stderr: Box::new(io::stderr()),
            stdin: Box::new(io::stdin()),
            stdout_tty: io::stdout().is_terminal(),
            stderr_tty: io::stderr().is_terminal(),
            stdin_tty: io::stdin().is_terminal(),
            config_dir: config::config_dir(&env),
            env,
            width: None,
        }
    }

    /// No terminal, no environment, no config directory; stdout and stderr captured.
    pub fn captured(stdin: impl Into<Vec<u8>>) -> (Self, Captured) {
        let captured = Captured::default();
        let host = Self {
            stdout: Box::new(captured.stdout.clone()),
            stderr: Box::new(captured.stderr.clone()),
            stdin: Box::new(io::Cursor::new(stdin.into())),
            stdout_tty: false,
            stderr_tty: false,
            stdin_tty: false,
            env: HashMap::new(),
            config_dir: None,
            width: None,
        };
        (host, captured)
    }
}

/// An in-memory stream.
#[derive(Clone, Debug, Default)]
pub struct Buffer(Arc<Mutex<Vec<u8>>>);

impl Buffer {
    pub fn text(&self) -> String {
        String::from_utf8_lossy(&self.0.lock().unwrap_or_else(|e| e.into_inner())).into_owned()
    }
}

impl Write for Buffer {
    fn write(&mut self, data: &[u8]) -> io::Result<usize> {
        self.0
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .extend_from_slice(data);
        Ok(data.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

/// What a [`Host::captured`] run wrote.
#[derive(Clone, Debug, Default)]
pub struct Captured {
    pub stdout: Buffer,
    pub stderr: Buffer,
}

#[derive(Clone)]
pub(super) struct Shared(Rc<RefCell<Box<dyn Write>>>);

impl Write for Shared {
    fn write(&mut self, data: &[u8]) -> io::Result<usize> {
        self.0.borrow_mut().write(data)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.0.borrow_mut().flush()
    }
}

/// What a generated command, or an [`Auth`] hook, runs with.
pub struct Ctx {
    pub app: App,
    pub globals: Globals,
    pub credentials: Credentials,
    /// stdout: `ctx.out.print(&response)?`, `ctx.out.items()`.
    pub out: Output,
    stdin: Box<dyn Read>,
    stderr: Shared,
    stdin_tty: bool,
    stderr_tty: bool,
    env: HashMap<String, String>,
    config_path: Option<PathBuf>,
    dry_run: Option<Recorder>,
}

impl Ctx {
    /// The bearer token for the SDK: `--api-key` or `<PREFIX>_API_KEY` when given, else the
    /// profile's credential through the [`Auth`] hook, under the config file's lock so that
    /// concurrent runs refresh once, saved back when the hook refreshed it.
    /// Under `--dry-run`, a placeholder.
    pub async fn token(&mut self) -> Result<String, CliError> {
        if self.dry_run.is_some() {
            return Ok(dry_run::TOKEN.to_owned());
        }
        if let Some(key) = &self.credentials.api_key {
            return Ok(key.clone());
        }
        let _lock = self.lock_profile();
        let mut credential = self.credentials.credential.clone();
        self.unseal(&mut credential)?;
        let unsealed = credential.clone();
        let token = self.app.auth.token(self, &mut credential).await?;
        if credential != unsealed {
            if let Err(error) = self.save_credential(&credential) {
                let _ = writeln!(self.stderr, "warning: {error}");
            }
        }
        self.credentials.credential = credential;
        Ok(token)
    }

    /// Reads the secrets of a credential that keeps them in the OS keyring.
    pub fn unseal(&self, credential: &mut Credential) -> Result<(), CliError> {
        keyring::load(self.app.name, self.profile(), credential)
    }

    /// Locks the config file and reloads the profile's credential; `None` without a stored one.
    fn lock_profile(&mut self) -> Option<config::ConfigLock> {
        if self.credentials.credential.is_empty() {
            return None;
        }
        let path = self.config_path.clone()?;
        let reloaded = ConfigFile::lock(&path).and_then(|lock| {
            let file = ConfigFile::load(&path)?;
            Ok((lock, file.profiles.get(self.profile()).cloned()))
        });
        match reloaded {
            Ok((lock, profile)) => {
                if let Some(profile) = profile {
                    self.credentials.credential = profile.credential;
                }
                Some(lock)
            }
            Err(error) => {
                self.debug(format_args!("refreshing without the config lock: {error}"));
                None
            }
        }
    }

    /// Saves a refreshed credential, its secrets where they were: the keyring, or the file,
    /// also when the keyring fails, rather than lose a rotated refresh token.
    fn save_credential(&self, credential: &Credential) -> Result<(), CliError> {
        let path = self.config_path()?;
        let mut credential = credential.clone();
        if keyring::sealed(&credential) {
            if let Err(error) = keyring::store(self.app.name, self.profile(), &mut credential) {
                let mut stderr = self.stderr.clone();
                let _ = writeln!(
                    stderr,
                    "warning: cannot write to the OS keyring ({error}): the secrets go to the config file"
                );
                credential.secrets = None;
            }
        }
        let mut file = ConfigFile::load(path)?;
        let profile = file.profiles.entry(self.profile().to_owned()).or_default();
        profile.credential = credential;
        file.save(path)
    }

    /// The config error of a command that needs a credential and has none.
    pub fn login_required(&self) -> CliError {
        CliError::config(format!(
            "not logged in: run `{} auth login`, pass --api-key or set {}_API_KEY",
            self.app.name, self.app.env_prefix
        ))
    }

    /// The selected profile, where `auth login` stores the credential.
    pub fn profile(&self) -> &str {
        &self.credentials.profile
    }

    /// A non-empty environment variable.
    pub fn env(&self, name: &str) -> Option<&str> {
        self.env
            .get(name)
            .map(String::as_str)
            .filter(|value| !value.is_empty())
    }

    pub fn stdin_tty(&self) -> bool {
        self.stdin_tty
    }

    /// Whether a person sees stderr, where logins print their prompts.
    pub fn stderr_tty(&self) -> bool {
        self.stderr_tty
    }

    pub(super) fn config_path(&self) -> Result<&std::path::Path, CliError> {
        self.config_path.as_deref().ok_or_else(|| {
            CliError::config(
                "no config directory: set XDG_CONFIG_HOME, or use --api-key and the environment",
            )
        })
    }

    /// Under `--dry-run`, what records the request the SDK's client would send: generated code
    /// gives the client an HTTP client calling [`Recorder::record`]. Commands not using the
    /// SDK must not act when this is `Some`.
    pub fn dry_run(&self) -> Option<&Recorder> {
        self.dry_run.as_ref()
    }

    /// The SDK's `max_retries`: `--retries`, `--no-retry` or `<PREFIX>_RETRIES`; `None` for its
    /// default.
    pub fn max_retries(&self) -> Option<u32> {
        match self.globals.no_retry {
            true => Some(0),
            false => self.globals.retries,
        }
    }

    /// The SDK's `timeout`: `--timeout` or `<PREFIX>_TIMEOUT`, `Some(None)` for none; `None` for
    /// its default.
    pub fn timeout(&self) -> Option<Option<Duration>> {
        let timeout = self.globals.timeout?;
        Some((!timeout.is_zero()).then_some(timeout))
    }

    /// With `--debug`, the log of each HTTP attempt, for an SDK middleware.
    pub fn attempts(&self) -> Option<Attempts> {
        (self.globals.debug && self.dry_run.is_none()).then_some(Attempts)
    }

    /// The base URL, `None` for the SDK's default.
    pub fn base_url(&self) -> Option<&str> {
        self.credentials.base_url.as_deref()
    }

    /// The base URL requests go to: [`Ctx::base_url`], else the SDK's default when known.
    pub fn api_base_url(&self) -> Option<&str> {
        self.base_url().or(self.app.default_base_url)
    }

    /// stdin, for `--data -`.
    pub fn stdin(&mut self) -> &mut dyn Read {
        &mut *self.stdin
    }

    pub fn stderr(&mut self) -> &mut dyn Write {
        &mut self.stderr
    }

    /// Writes `debug: <message>` to stderr with `--debug`.
    pub fn debug(&mut self, message: impl fmt::Display) {
        if self.globals.debug {
            let _ = writeln!(self.stderr, "debug: {message}");
        }
    }

    pub fn print<T: Serialize + ?Sized>(&mut self, value: &T) -> Result<(), CliError> {
        self.out.print(value)
    }

    pub fn items(&mut self) -> Items<'_> {
        self.out.items()
    }

    /// The events of a stream, printed as they arrive.
    pub fn events(&mut self) -> Items<'_> {
        self.out.events()
    }
}

/// `main` of a generated CLI: `fn main() -> ExitCode { app::run(APP, cli(), dispatch) }`.
/// `dispatch` runs once per command, and once per tool call under `mcp`.
pub fn run<F, Fut>(app: App, cmd: Command, dispatch: F) -> ExitCode
where
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    ExitCode::from(run_with(
        app,
        cmd,
        std::env::args_os(),
        Host::system(),
        dispatch,
    ))
}

/// [`run`] against any host and arguments; returns the exit code.
pub fn run_with<I, T, F, Fut>(app: App, cmd: Command, args: I, host: Host, dispatch: F) -> u8
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    run_once(app, cmd, args, host, &dispatch)
}

/// One command line; its error, if any, rendered on stderr.
fn run_once<I, T, F, Fut>(app: App, cmd: Command, args: I, host: Host, dispatch: &F) -> u8
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
    F: Fn(Ctx, ArgMatches) -> Fut,
    Fut: Future<Output = Result<(), CliError>>,
{
    let (stdout_tty, stderr_tty) = (host.stdout_tty, host.stderr_tty);
    let color_allowed = color_allowed(&host.env);
    let mut stdout = Shared(Rc::new(RefCell::new(Box::new(io::sink()))));
    let mut stderr = stdout.clone();
    let line = parse(app, cmd, args, host, None, |out, err| {
        (stdout, stderr) = (out.clone(), err.clone());
    });
    let failure = match line.and_then(|line| line.run_blocking(dispatch)) {
        Ok(()) => return exit::OK,
        Err(failure) => failure,
    };
    match failure {
        Failure::Clap(error, json_errors) => {
            let (out, tty): (&mut dyn Write, bool) = match error.kind() {
                ClapErrorKind::DisplayHelp | ClapErrorKind::DisplayVersion => {
                    (&mut stdout, stdout_tty)
                }
                _ => (&mut stderr, stderr_tty && !json_errors),
            };
            clap_error(&error, out, tty, tty && color_allowed)
        }
        Failure::Cli(error, _) if error.is_broken_pipe() => exit::OK,
        Failure::Cli(error, style) => {
            let _ = error.render(&mut stderr, style);
            let _ = stderr.flush();
            error.exit_code()
        }
    }
}

/// Why a command line failed: clap's error (help and version included), whether errors are
/// JSON; or the CLI's, and how to render it.
pub(super) enum Failure {
    Clap(clap::Error, bool),
    Cli(CliError, ErrorStyle),
}

impl Failure {
    /// As one error, for callers that do not print: `mcp`.
    pub(super) fn into_error(self) -> CliError {
        match self {
            Self::Clap(error, _) => {
                let message = error.render().to_string();
                let message = message.trim().trim_start_matches("error: ");
                let message = message
                    .split("\n\nUsage:")
                    .next()
                    .unwrap_or(message)
                    .trim_end_matches("\n\nFor more information, try '--help'.");
                CliError::usage(message)
            }
            Self::Cli(error, _) => error,
        }
    }
}

fn color_allowed(env: &HashMap<String, String>) -> bool {
    env.get("NO_COLOR").is_none_or(String::is_empty)
        && env.get("TERM").is_none_or(|term| term != "dumb")
}

/// One command line, parsed with its global options and environment, ready to run;
/// `streams` gets stdout and stderr first, `report` what a list printed.
pub(super) fn parse<I, T>(
    app: App,
    cmd: Command,
    args: I,
    host: Host,
    report: Option<Report>,
    streams: impl FnOnce(&Shared, &Shared),
) -> Result<Line, Failure>
where
    I: IntoIterator<Item = T>,
    T: Into<OsString> + Clone,
{
    let color_allowed = color_allowed(&host.env);
    let Host {
        stdout,
        stderr,
        stdin,
        stdout_tty,
        stderr_tty,
        stdin_tty,
        env,
        config_dir,
        width,
    } = host;
    let stdout = Shared(Rc::new(RefCell::new(stdout)));
    let stderr = Shared(Rc::new(RefCell::new(stderr)));
    streams(&stdout, &stderr);
    let format_env = format!("{}_FORMAT", app.env_prefix);
    let env_format = match env.get(&format_env).filter(|value| !value.is_empty()) {
        None => None,
        Some(name) => match Format::parse(name) {
            Some(format) => Some(format),
            None => {
                let message =
                    format!("{format_env}: unknown format `{name}`: json, jsonl, yaml or table");
                return Err(Failure::Cli(
                    CliError::usage(message),
                    ErrorStyle::default(),
                ));
            }
        },
    };
    let json_errors = env_format.is_some_and(Format::is_json);
    let matches = cmd
        .clone()
        .try_get_matches_from(args)
        .map_err(|error| Failure::Clap(error, json_errors))?;

    let mut globals = globals(&matches);
    globals.format = globals.format.or(env_format);
    if let Err(error) = retry::apply_env(&mut globals, &env, app.env_prefix) {
        let human = stderr_tty && !globals.format.is_some_and(Format::is_json);
        let style = ErrorStyle {
            human,
            ..ErrorStyle::default()
        };
        return Err(Failure::Cli(error, style));
    }
    let color = |tty: bool| tty && color_allowed && !globals.no_color;
    let error_style = ErrorStyle {
        human: stderr_tty && !globals.format.is_some_and(Format::is_json),
        color: color(stderr_tty),
        debug: globals.debug,
    };
    let style = Style {
        format: globals.format,
        tty_format: app.default_format,
        tty: stdout_tty,
        color: color(stdout_tty) && !globals.format.is_some_and(Format::is_json),
        pretty: globals.pretty,
        max_items: globals.max_items,
        all: globals.all,
        width,
    };
    let session = Session {
        app,
        cmd,
        env,
        config_path: config_dir
            .as_ref()
            .map(|dir| config::config_path(dir, app.name)),
        config_dir,
        stdin,
        stdin_tty,
        stderr_tty,
        stderr,
        report,
    };
    Ok(Line {
        session,
        recorder: globals.dry_run.then(Recorder::default),
        matches,
        globals,
        style,
        stdout,
        error_style,
    })
}

/// A command line [`parse`] made ready to run.
pub(super) struct Line {
    session: Session,
    matches: ArgMatches,
    globals: Globals,
    style: Style,
    stdout: Shared,
    recorder: Option<Recorder>,
    error_style: ErrorStyle,
}

impl Line {
    /// Runs the command on a Tokio runtime of its own.
    fn run_blocking<F, Fut>(mut self, dispatch: &F) -> Result<(), Failure>
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        let result = match self.step() {
            Ok(Step::Done) => Ok(()),
            Ok(Step::Serve(args, mut out)) => mcp::Server::new(&self.session, &args, &self.globals)
                .and_then(|server| server.serve(&mut self.session, out.writer(), dispatch)),
            Ok(Step::Run(ctx, job)) => tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .map_err(CliError::from)
                .and_then(|runtime| runtime.block_on(job.run(*ctx, dispatch))),
            Err(error) => Err(error),
        };
        self.finish(result)
    }

    /// Runs the command on the caller's runtime: what `mcp` does for each tool call.
    pub(super) async fn run<F, Fut>(mut self, dispatch: &F) -> Result<(), Failure>
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        let result = match self.step() {
            Ok(Step::Done) => Ok(()),
            Ok(Step::Serve(..)) => Err(CliError::usage("mcp: a tool cannot serve another server")),
            Ok(Step::Run(ctx, job)) => job.run(*ctx, dispatch).await,
            Err(error) => Err(error),
        };
        self.finish(result)
    }

    fn step(&mut self) -> Result<Step, CliError> {
        let (matches, globals) = (self.matches.clone(), self.globals.clone());
        let recorder = self.recorder.clone();
        self.session
            .prepare(matches, globals, self.style, &self.stdout, recorder)
    }

    /// With `--dry-run`, prints the request recorded instead of the result.
    fn finish(self, result: Result<(), CliError>) -> Result<(), Failure> {
        let result = match self.recorder.and_then(|recorder| recorder.take()) {
            Some(request) => (|| {
                let jq = self.globals.jq.as_deref().map(Jq::compile).transpose()?;
                Output::new(Box::new(self.stdout), self.style, jq).print(&request)
            })(),
            None => result,
        };
        result.map_err(|error| Failure::Cli(error, self.error_style))
    }
}

/// What [`Session::prepare`] leaves to do.
enum Step {
    /// A built-in that ran.
    Done,
    /// `mcp`, with its arguments and stdout.
    Serve(ArgMatches, Output),
    /// A command that needs the network.
    Run(Box<Ctx>, Job),
}

enum Job {
    Login(ArgMatches),
    Logout,
    Token,
    Dispatch(ArgMatches),
}

impl Job {
    async fn run<F, Fut>(self, mut ctx: Ctx, dispatch: &F) -> Result<(), CliError>
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        match self {
            Self::Login(args) => auth::login(&mut ctx, &args).await,
            Self::Logout => auth::logout(&mut ctx).await,
            Self::Token => auth::token(&mut ctx).await,
            Self::Dispatch(matches) => dispatch(ctx, matches).await,
        }
    }
}

fn clap_error(error: &clap::Error, out: &mut dyn Write, human: bool, color: bool) -> u8 {
    let rendered = error.render();
    let help = !error.use_stderr()
        || error.kind() == ClapErrorKind::DisplayHelpOnMissingArgumentOrSubcommand;
    let written = if help || human {
        let text = if color {
            rendered.ansi().to_string()
        } else {
            rendered.to_string()
        };
        out.write_all(text.as_bytes())
    } else {
        let message = rendered.to_string();
        let message = message.trim().trim_start_matches("error: ");
        CliError::usage(message).render(out, ErrorStyle::default())
    };
    let _ = written.and_then(|()| out.flush());
    u8::try_from(error.exit_code()).unwrap_or(exit::USAGE)
}

pub(super) struct Session {
    pub(super) app: App,
    pub(super) cmd: Command,
    pub(super) env: HashMap<String, String>,
    pub(super) config_dir: Option<PathBuf>,
    config_path: Option<PathBuf>,
    pub(super) stdin: Box<dyn Read + Send>,
    stdin_tty: bool,
    stderr_tty: bool,
    pub(super) stderr: Shared,
    report: Option<Report>,
}

impl Session {
    /// Runs a built-in, or prepares the context of a command that needs the network.
    fn prepare(
        &mut self,
        matches: ArgMatches,
        globals: Globals,
        style: Style,
        stdout: &Shared,
        dry_run: Option<Recorder>,
    ) -> Result<Step, CliError> {
        let jq = globals.jq.as_deref().map(Jq::compile).transpose()?;
        let mut out = Output::new(Box::new(stdout.clone()), style, jq)
            .with_hints(Box::new(self.stderr.clone()))
            .with_report(self.report.clone());
        match matches.subcommand() {
            Some(("completion", sub)) => {
                let shell = *sub.get_one::<Shell>("shell").expect("required");
                let mut script = Vec::new();
                clap_complete::generate(shell, &mut self.cmd, self.app.name, &mut script);
                out.writer().write_all(&script)?;
                out.writer().flush()?;
                return Ok(Step::Done);
            }
            Some(("man", sub)) => {
                self.man(sub.get_one::<PathBuf>("out-dir"), &mut out)?;
                return Ok(Step::Done);
            }
            Some(("schema", sub)) => {
                self.schema(sub, &mut out)?;
                return Ok(Step::Done);
            }
            Some(("agents", _)) => {
                let guide = agents_guide(self.app.name, self.app.env_prefix);
                out.writer().write_all(guide.as_bytes())?;
                out.writer().flush()?;
                return Ok(Step::Done);
            }
            Some(("mcp", sub)) => return Ok(Step::Serve(sub.clone(), out)),
            _ => {}
        }

        let overrides = Overrides {
            profile: globals.profile.as_deref(),
            api_key: globals.api_key.as_deref(),
            base_url: globals.base_url.as_deref(),
        };
        let prefix = self.app.env_prefix;
        let auth = matches.subcommand_matches("auth");
        let explicit_key = auth.is_none()
            && (globals.api_key.is_some()
                || self
                    .env
                    .get(&format!("{prefix}_API_KEY"))
                    .is_some_and(|key| !key.is_empty()));
        let file = match self.config() {
            Err(error) if explicit_key => {
                self.debug_ignored(globals.debug, &error);
                ConfigFile::default()
            }
            file => file?,
        };
        let credentials = match auth {
            Some(_) => config::resolve_lenient(&file, overrides, &self.env, prefix),
            None => match config::resolve(&file, overrides, &self.env, prefix) {
                Err(error) if explicit_key => {
                    self.debug_ignored(globals.debug, &error);
                    config::resolve_lenient(&file, overrides, &self.env, prefix)
                }
                credentials => credentials?,
            },
        };
        if globals.debug && auth.is_none() {
            self.debug_credentials(&credentials);
        }
        let stdin = std::mem::replace(&mut self.stdin, Box::new(io::empty()));
        let mut ctx = Ctx {
            app: self.app,
            globals,
            credentials,
            out,
            stdin,
            stderr: self.stderr.clone(),
            stdin_tty: self.stdin_tty,
            stderr_tty: self.stderr_tty,
            env: std::mem::take(&mut self.env),
            config_path: self.config_path.clone(),
            dry_run,
        };
        let job = match auth.map(ArgMatches::subcommand) {
            Some(Some(("login", args))) => Job::Login(args.clone()),
            Some(Some(("logout", _))) => Job::Logout,
            Some(Some(("status", _))) => return auth::status(&mut ctx).map(|()| Step::Done),
            Some(Some(("token", _))) => Job::Token,
            Some(_) => return auth::profiles(&mut ctx, &file).map(|()| Step::Done),
            None => Job::Dispatch(matches),
        };
        Ok(Step::Run(Box::new(ctx), job))
    }

    fn schema(&self, args: &ArgMatches, out: &mut Output) -> Result<(), CliError> {
        let schema = Schema::parse(self.app.schema)?;
        let words: Vec<String> = args
            .get_many::<String>("command")
            .into_iter()
            .flatten()
            .flat_map(|word| word.split_whitespace())
            .map(str::to_owned)
            .collect();
        if let Some(described) = schema.describe(&words.join(" "), args.get_flag("response")) {
            return out.print(&described);
        }
        let mut index = schema.index(&words);
        let hidden = hidden(&schema);
        index.retain(|entry| !hidden.iter().any(|words| entry["command"] == *words));
        if index.is_empty() {
            return Err(CliError::usage(format!(
                "schema: no command `{}`: `{} schema` lists them",
                words.join(" "),
                self.app.name
            )));
        }
        out.print(&index)
    }

    fn config(&self) -> Result<ConfigFile, CliError> {
        self.config_path
            .as_deref()
            .map_or_else(|| Ok(ConfigFile::default()), ConfigFile::load)
    }

    /// A config error an explicit API key makes moot, a warning with `--debug`.
    fn debug_ignored(&mut self, debug: bool, error: &CliError) {
        if debug {
            let _ = writeln!(
                self.stderr,
                "debug: warning: {error} (ignored: the API key is explicit)"
            );
        }
    }

    fn debug_credentials(&mut self, credentials: &Credentials) {
        let config = self
            .config_path
            .as_ref()
            .map_or_else(|| "none".to_owned(), |path| path.display().to_string());
        let (auth, source) = match &credentials.api_key {
            Some(key) => (
                format!("api key {}", config::mask(key)),
                credentials.api_key_source.clone(),
            ),
            None if credentials.credential.is_empty() => ("none".to_owned(), Source::Default),
            None => {
                let mut credential = credentials.credential.clone();
                let status =
                    match keyring::load(self.app.name, &credentials.profile, &mut credential) {
                        Ok(()) => self.app.auth.status(&credential),
                        Err(error) => error.to_string(),
                    };
                (status, Source::Profile(credentials.profile.clone()))
            }
        };
        let base_url = match credentials
            .base_url
            .as_deref()
            .or(self.app.default_base_url)
        {
            Some(url) => redact_userinfo(url),
            None => "the SDK's default".to_owned(),
        };
        let _ = writeln!(
            self.stderr,
            "debug: config {config}\ndebug: profile `{}` ({})\ndebug: auth {auth} ({source})\ndebug: base url {base_url} ({})",
            credentials.profile, credentials.profile_source, credentials.base_url_source,
        );
    }

    fn man(&self, out_dir: Option<&PathBuf>, out: &mut Output) -> Result<(), CliError> {
        match out_dir {
            Some(dir) => {
                std::fs::create_dir_all(dir)?;
                clap_mangen::generate_to(self.cmd.clone(), dir)?;
            }
            None => clap_mangen::Man::new(self.cmd.clone()).render(out.writer())?,
        }
        Ok(out.writer().flush()?)
    }
}

/// `url` without its userinfo, which may be a password or a token: `https://***@host/`.
pub(super) fn redact_userinfo(url: &str) -> String {
    let Some((scheme, rest)) = url.split_once("://") else {
        return url.to_owned();
    };
    let authority = rest.split(['/', '?', '#']).next().unwrap_or_default();
    match authority.rsplit_once('@') {
        Some((_, host)) => format!("{scheme}://***@{host}{}", &rest[authority.len()..]),
        None => url.to_owned(),
    }
}

/// The guide `agents` prints: how programs drive the CLI.
fn agents_guide(name: &str, prefix: &str) -> String {
    format!(
        "\
{name}, for scripts and agents

Discover
  {name} schema [<resource>]       the commands: method, path, summary
  {name} schema <resource> <op>    JSON Schema of its parameters and body, an example
  {name} schema ... --response     of what it prints
  {name} <resource> <op> --help    flags, (required) ones, an example
  {name} ... --dry-run             the request as JSON, not sent, no credential needed
  {name} mcp                       each op as an MCP tool on stdio (--read-only, --tools, --list)

Input
  Path parameters are positional, query and header parameters flags. A body is
  -d JSON, -d @file or -d - (stdin), field flags (--name x) overriding its fields.
  Input is checked first: unknown fields and values, types, ranges, lengths,
  patterns, formats, missing required fields fail at once (exit 2, in
  error.errors); --allow-unknown-fields sends unknown ones. Lists of enums or
  numbers take a,b,c.

Output, on stdout
  Off a terminal: compact JSON; lists and streams one item per line (jsonl), as
  pages arrive. --format json|jsonl|yaml|table or {prefix}_FORMAT; --pretty.
  --jq FILTER runs on each item, on the whole array with --format json; strings
  print raw. Lists fetch every page unless a page or cursor flag picks one; on a
  terminal the first, --all for all. --max-items N stops after N.
  Files need -o FILE (prints {{\"path\",\"bytes\",\"content_type\"}}) or -o - (stdout).

Errors, on stderr: one JSON line
  {{\"error\":{{\"kind\",\"status\",\"message\",\"body\",\"request_id\",\"retryable\",\"retry_after\",\"errors\"}}}}
  exit 0 ok, 1 internal, 2 usage or invalid input, 3 API 4xx, 4 API 5xx,
  5 network or timeout, 6 credentials or config, 7 --jq failed (response printed).
  Retried: no response, 408, 429, 5xx, if idempotent or with an idempotency key;
  --retries N (2), --no-retry, --timeout SECS; {prefix}_RETRIES, {prefix}_TIMEOUT.

Credentials: {prefix}_API_KEY or --api-key, {prefix}_BASE_URL, --profile;
  `{name} auth login` (--api-key-stdin; --device prints JSON), auth status, auth token.
"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    const APP: App = App {
        name: "acme",
        env_prefix: "ACME",
        auth: &auth::ApiKey,
        default_base_url: None,
        default_format: None,
        schema: &[],
    };

    fn cli() -> Command {
        command(
            &APP,
            Command::new("acme").subcommand(Command::new("things")),
        )
    }

    #[test]
    fn globals_are_read_wherever_they_appear() {
        let matches = cli()
            .try_get_matches_from([
                "acme",
                "--format",
                "yaml",
                "things",
                "--jq",
                ".id",
                "--max-items",
                "3",
                "--debug",
            ])
            .unwrap();
        let expected = Globals {
            format: Some(Format::Yaml),
            jq: Some(".id".into()),
            max_items: Some(3),
            debug: true,
            ..Globals::default()
        };
        assert_eq!(globals(&matches), expected);
        assert_eq!(
            globals(matches.subcommand_matches("things").unwrap()),
            expected
        );
    }

    #[test]
    fn invalid_formats_are_rejected_by_the_parser() {
        let error = cli()
            .try_get_matches_from(["acme", "things", "--format", "xml"])
            .unwrap_err();
        assert_eq!(error.kind(), ClapErrorKind::InvalidValue);
    }

    #[test]
    fn builtins_are_registered() {
        let cmd = cli();
        for name in BUILTINS {
            assert!(cmd.find_subcommand(name).is_some(), "{name}");
        }
        assert!(cmd.find_subcommand("man").unwrap().is_hide_set());
        let auth = cmd.find_subcommand("auth").unwrap();
        for name in ["login", "logout", "profiles"] {
            assert!(auth.find_subcommand(name).is_some(), "auth {name}");
        }
    }

    #[test]
    fn the_command_tree_is_valid() {
        cli().debug_assert();
    }

    #[test]
    fn perseid_toml_hides_commands_and_picks_the_format_of_terminals() {
        const SCHEMA: &str = r#"{
          "resources": {"things": "things", "labels": "things labels"},
          "cli": {"operations": {"things_archive": {"hidden": true},
                                 "things_labels_list": {"hidden": true},
                                 "auth_login": {"hidden": true}}},
          "commands": {
            "things.list": {"resource": "things", "command": "list", "method": "GET", "path": "/things"},
            "things.archive": {"resource": "things", "command": "archive", "method": "POST", "path": "/archive"},
            "labels.list": {"resource": "labels", "command": "list", "method": "GET", "path": "/labels"}
          }
        }"#;
        let app = App {
            default_format: Some(Format::Yaml),
            schema: &[SCHEMA],
            ..APP
        };
        let root = Command::new("acme").subcommand(
            Command::new("things")
                .subcommand(Command::new("list"))
                .subcommand(Command::new("archive"))
                .subcommand(Command::new("labels").subcommand(Command::new("list"))),
        );
        let cmd = command(&app, root);
        let things = cmd.find_subcommand("things").unwrap();
        let hidden = |cmd: &Command, name: &str| cmd.find_subcommand(name).unwrap().is_hide_set();
        assert!(!hidden(&cmd, "things") && !hidden(things, "list"));
        assert!(hidden(things, "archive"), "hidden in perseid.toml");
        assert!(hidden(things, "labels"), "every command of it is hidden");
        assert!(!hidden(cmd.find_subcommand("auth").unwrap(), "login"));
        assert!(cmd
            .try_get_matches_from(["acme", "things", "archive"])
            .is_ok());
        let format = command(&app, Command::new("acme"));
        let format = (format.get_arguments())
            .find(|arg| arg.get_id() == ids::FORMAT)
            .and_then(Arg::get_help)
            .unwrap()
            .to_string();
        assert!(format.contains("[default: yaml on a terminal, else json;"));
    }

    #[test]
    fn userinfo_is_redacted() {
        assert_eq!(
            redact_userinfo("https://jane:s3cret@api.acme.dev/v1?a=b@c"),
            "https://***@api.acme.dev/v1?a=b@c"
        );
        assert_eq!(
            redact_userinfo("http://tok@localhost:8080"),
            "http://***@localhost:8080"
        );
        assert_eq!(
            redact_userinfo("https://api.acme.dev/v1/@me"),
            "https://api.acme.dev/v1/@me"
        );
        assert_eq!(redact_userinfo("not a url"), "not a url");
    }

    /// Rotates the access token on every call.
    struct Rotating;

    impl Auth for Rotating {
        fn login<'a>(
            &'a self,
            _: &'a mut Ctx,
            _: &'a ArgMatches,
        ) -> auth::BoxFuture<'a, Result<Credential, CliError>> {
            Box::pin(async { Ok(Credential::default()) })
        }

        fn token<'a>(
            &'a self,
            _: &'a mut Ctx,
            credential: &'a mut Credential,
        ) -> auth::BoxFuture<'a, Result<String, CliError>> {
            let next = format!("{}+", credential.access_token.as_deref().unwrap_or("at"));
            credential.access_token = Some(next.clone());
            Box::pin(async move { Ok(next) })
        }
    }

    fn ctx(config_path: PathBuf, flags: Overrides<'_>) -> Ctx {
        let file = ConfigFile::load(&config_path).unwrap();
        Ctx {
            app: App {
                auth: &Rotating,
                ..APP
            },
            globals: Globals::default(),
            credentials: config::resolve(&file, flags, &HashMap::new(), "ACME").unwrap(),
            out: Output::new(Box::new(io::sink()), Style::default(), None),
            stdin: Box::new(io::empty()),
            stderr: Shared(Rc::new(RefCell::new(Box::new(io::sink())))),
            stdin_tty: false,
            stderr_tty: false,
            env: HashMap::new(),
            config_path: Some(config_path),
            dry_run: None,
        }
    }

    #[test]
    fn an_explicit_key_skips_the_hook_whose_changes_are_saved() {
        let dir = tempfile::tempdir().unwrap();
        let path = config::config_path(dir.path(), "acme");
        let mut file = ConfigFile::default();
        let stored = Credential {
            access_token: Some("at".into()),
            ..Credential::default()
        };
        file.login("default", stored, None);
        file.save(&path).unwrap();
        let runtime = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();

        let flags = Overrides {
            api_key: Some("sk_flag"),
            ..Overrides::default()
        };
        let mut explicit = ctx(path.clone(), flags);
        assert_eq!(runtime.block_on(explicit.token()).unwrap(), "sk_flag");

        let mut hooked = ctx(path.clone(), Overrides::default());
        assert_eq!(runtime.block_on(hooked.token()).unwrap(), "at+");
        assert_eq!(runtime.block_on(hooked.token()).unwrap(), "at++");
        let saved = &ConfigFile::load(&path).unwrap().profiles["default"];
        assert_eq!(saved.credential.access_token.as_deref(), Some("at++"));
    }
}
